fn setup(){
 assert!(!r("build-plan.json").exists());let m=read(MANIFEST);let files=m["source_files_sha256"].as_object().unwrap();assert_eq!(files.len(),174);let mut pins=BTreeMap::new();
 for(f,h)in files{let from=Path::new(Z).join(f);assert_eq!(hash(&from),h.as_str().unwrap());let to=r("source").join(f);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(&from,&to).unwrap();pin(&mut pins,from);pin(&mut pins,to);}
 let module=r("source/crates/zopro-core/src/msm_affine/g2_borrowed/dual_plane.rs");fs::create_dir_all(module.parent().unwrap()).unwrap();fs::copy(r("dual_plane.rs"),&module).unwrap();pin(&mut pins,&module);
 let file="crates/zopro-core/src/msm_affine/g2_borrowed.rs";let p=r("source").join(file);let original=fs::read_to_string(&p).unwrap();
 let suffix="\n#[cfg(zopro_g2_dual_plane)] mod dual_plane;\n#[cfg(zopro_g2_dual_plane)] pub(super) fn dual_credit(bits:usize,windows:usize,parts:usize)->Option<crate::preparation::Reservation>{dual_plane::reserve_query(bits,windows,parts)}\n#[cfg(zopro_g2_dual_plane)] pub(super) fn try_dual_window(bases:&[G2Affine],short:&[[u64;4]],w:usize,bits:usize,credit:&crate::preparation::Reservation)->Option<Vec<G2Affine>>{dual_plane::try_window(bases,short,w,bits,credit)}\n";
 let modified=format!("{original}{suffix}");assert_eq!(modified.strip_suffix(suffix).unwrap(),original);fs::write(&p,modified).unwrap();pin(&mut pins,&p);
 let phi="crates/zopro-core/src/msm_affine/g2_phi.rs";let pp=r("source").join(phi);let original_phi=fs::read_to_string(&pp).unwrap();
 let edits=[("    let windows = 127usize.div_ceil(bits);","    let windows = 127usize.div_ceil(bits); #[cfg(zopro_g2_dual_plane)] let dual_credit=super::g2_borrowed::dual_credit(bits,windows,parts);"),
 ("                    hb_window(&bases[start..end], &short[start..end], w, bits)","                    { #[cfg(zopro_g2_dual_plane)] if let Some(credit)=dual_credit.as_ref(){if let Some(value)=super::g2_borrowed::try_dual_window(&bases[start..end],&short[start..end],w,bits,credit){return value;}} hb_window(&bases[start..end], &short[start..end], w, bits) }")];
 let mut text=original_phi.clone();for(before,after)in edits{assert_eq!(text.matches(before).count(),1);text=text.replace(before,after);}let mut reverse=text.clone();for(before,after)in edits{reverse=reverse.replace(after,before);}assert_eq!(reverse,original_phi);fs::write(&pp,text).unwrap();pin(&mut pins,&pp);
 let exact=files.iter().filter(|(f,h)|hash(r("source").join(f))==h.as_str().unwrap()).count();assert_eq!(exact,172);
 save(r("source-audit.json"),&json!({"original_files":174,"private_files":175,"originals_exact":172,"reverse174_exact":true,"file":file,"suffix":suffix,"phi_file":phi,"phi_edits":edits,"new_module":"crates/zopro-core/src/msm_affine/g2_borrowed/dual_plane.rs","original_line_numbers_preserved":true,"field_G1_solver_key_scheduler_forecasts_exact":true,"full_new_leaf_times_windows_parts_reserved_once_per_query":true,"production_changed":false}));
 let history=["docs/benchmarks/2026-10-22-universal-g1-bucket-horner/README.md","docs/benchmarks/2026-10-24-g2-interleaved-phi/README.md","docs/benchmarks/2026-10-24-g2-guarded-phi/README.md","docs/benchmarks/2026-10-26-g2-level-tree/README.md","docs/benchmarks/2026-10-25-batched-steal/README.md"];
 let mut hist=BTreeMap::new();for f in history{pin(&mut hist,Path::new(Z).join(f));pin(&mut pins,Path::new(Z).join(f));}save(r("history-audit.json"),&json!({"closed_trials":hist,"difference":"joint two-plane borrowed pending/inverse;phi on finished bucket sums;no transformed-base cache or level tree;serial512merges","new_performance_claim":false}));
 let flags=m["rustflags"].as_str().unwrap();fs::write(r("native-flags.txt"),flags).unwrap();let cargo=r("source/Cargo.toml");let mut steps=Vec::new();
 for label in ["control","candidate"]{let flag=if label=="control"{flags.to_string()}else{format!("{flags} --cfg zopro_g2_dual_plane")};let env=json!({"RUSTFLAGS":flag,"CARGO_TARGET_DIR":r(format!("target-{label}")),"CARGO_BUILD_JOBS":"16","RAYON_NUM_THREADS":"4","ZOPRO_CPU_DEDUP":"1","ZOPRO_CPU_ZERO_AWARE_GROUPS":"1","ZOPRO_CPU_PACKED":"1","ZOPRO_CPU_DIRECT":"1","ZOPRO_CPU_CANONICAL_BATCH":"1","ZOPRO_CPU_VECTOR_INVERSE":"1","ZOPRO_CPU_G2_PREFIX_RECORDS":"1","ZOPRO_CPU_G1_SCRATCH_STORE":"2"});
  let required=if label=="candidate"{vec!["msm_affine::g2_borrowed::dual_plane::tests::all_buckets_match_complete_signed_component_oracle","msm_affine::g2_borrowed::dual_plane::tests::checked_costs_and_denial_preserve_inputs"]}else{vec![]};
  steps.push(json!({"kind":"command","name":format!("zopro-core-{label}"),"argv":["cargo","test","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-core","--lib","--","--test-threads=1"],"environment":env,"unfiltered":true,"required_tests":required,"timeout_seconds":1800}));
  steps.push(json!({"kind":"command","name":format!("zopro-prover-{label}"),"argv":["cargo","test","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-prover","--lib","--test","cubic","--","--test-threads=1"],"environment":env,"unfiltered":true,"timeout_seconds":1800}));
  steps.push(json!({"kind":"command","name":format!("libraries-{label}"),"argv":["cargo","build","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-bench","--lib","--message-format=json"],"environment":env,"timeout_seconds":1800}));
  steps.push(json!({"kind":"command","name":format!("freeze-{label}"),"argv":[r("native-helper"),"freeze",label],"environment":env,"timeout_seconds":180}));
  steps.push(json!({"kind":"link-sdk","name":label,"artifacts":r(format!("frozen-{label}-cargo.jsonl")),"driver":Path::new(Z).join("crates/zopro-bench/examples/cpu-sdk.rs"),"additional_sources":[Path::new(Z).join("crates/zopro-bench/examples/support/perf.rs")],"timeout_seconds":600}));
 }
 for f in ["native.rs","native-helper","setup.rs","dual_plane.rs","design.md","source-audit.json","history-audit.json","native-flags.txt"]{pin(&mut pins,r(f));}pin(&mut pins,MANIFEST);
 save(r("build-pins.json"),&json!(pins));save(r("build-plan.json"),&json!({"version":1,"source_pins":r("build-pins.json"),"steps":steps}));println!("Prepared10native steps175source/172exact/reverse174;two-plane workspace reserved onceperquery");
}
